// One-time unit migration: preserve purchasing power and historical accounting.
export function upgradeEconomy(s){if(s.currencyVersion===undefined){s.profile.coins*=100;for(const m of s.missions)m.coins*=100;for(const r of s.rewards){r.cost*=100;r.increase*=100;}for(const h of s.history)if(typeof h.coins==='number')h.coins*=100;s.currencyVersion=2;}if(s.currencyVersion!==2)throw Error('Unsupported currency units.');for(const m of s.missions)m.currencyVersion=2;s.settings.attention??={focus:true,reducedMotion:false};if(typeof s.settings.attention.focus!=='boolean'||typeof s.settings.attention.reducedMotion!=='boolean')throw Error('Invalid attention settings.');return s;}
export const money=value=>'€$ '+Number(value).toLocaleString(undefined,{maximumFractionDigits:2});
